    var isConfirmedActive: Bool { isActive == true }

    /// Trips in departure order. Trips without a usable departure sort last.
    var tripsByDeparture: [Trip] {
        trips.sorted { lhs, rhs in
            switch (lhs.departure, rhs.departure) {
            case let (l?, r?): l < r
            case (.some, nil): true
            default: false
            }
