                    }
                }
            }

            ForEach(tripGroups, id: \.title) { group in
                Section(group.title) {
                    ForEach(group.trips) { TripRow(trip: $0) }
                }
            }

            if route.trips.isEmpty {
                ContentUnavailableView("No trips listed", systemImage: "calendar.badge.exclamationmark")
            }
        }
        .navigationTitle(route.routeID)
        .navigationBarTitleDisplayMode(.inline)
        .safeAreaInset(edge: .bottom) {
            if let snapshotTakenAt {
                Text("Timetable as of \(IST.dateTime(snapshotTakenAt)). Seats and status may have changed since.")
                    .font(.caption2)
                    .foregroundStyle(.secondary)
                    .padding(8)
                    .frame(maxWidth: .infinity)
                    .background(.bar)
            }
        }
    }

    private var serviceText: String {
        switch route.isActive {
        case true?: "In service"
        case false?: "Not in service"
        case nil: "Unknown"
        }
    }

    private var tripGroups: [(title: String, trips: [Trip])] {
        let sorted = route.tripsByDeparture
        let morning = sorted.filter { $0.departure.map { IST.hour($0) < 12 } ?? false }
        let later = sorted.filter { $0.departure.map { IST.hour($0) >= 12 } ?? false }
        let unknown = sorted.filter { $0.departure == nil }
        return [("Morning", morning), ("Afternoon & evening", later), ("Time unknown", unknown)]
            .filter { !$0.1.isEmpty }
    }
}

struct TripRow: View {
    let trip: Trip

    var body: some View {
        VStack(alignment: .leading, spacing: 6) {
            HStack(alignment: .firstTextBaseline) {
                Text(timesText)
                    .font(.body.monospacedDigit().weight(.semibold))
                Spacer()
                statusBadge
            }
            HStack(spacing: 6) {
                if let duration = trip.scheduledDuration {
                    Text(IST.duration(duration))
                }
                Text("· \(seatsText)")
                    .foregroundStyle(seatsAreTight ? .red : .secondary)
                if let pct = trip.onTimePercent {
                    Text("· \(pct, format: .number.precision(.fractionLength(0)))% on time")
                }
            }
            .font(.caption)
            .foregroundStyle(.secondary)

            Text(trip.tripID)
                .font(.caption2.monospaced())
                .foregroundStyle(.tertiary)

            ForEach(visibleIssues, id: \.self) { message in
                Label(message, systemImage: "exclamationmark.triangle")
                    .font(.caption)
                    .foregroundStyle(.orange)
            }
        }
        .padding(.vertical, 2)
    }

    private var timesText: String {
        let departure = trip.departure.map(IST.time) ?? "--:--"
        let arrival = trip.trustedArrival.map(IST.time) ?? "--:--"
        return "\(departure) → \(arrival)"
    }

    private var seatsText: String {
        switch trip.seats {
        case .available(let left, let total): "\(left) of \(total) seats left"
        case .full: "Full"
        case .unknown: "Seats unknown"
        }
    }

    private var seatsAreTight: Bool {
        switch trip.seats {
        case .available(let left, _): left <= 3
        case .full: true
        case .unknown: false
        }
    }

    @ViewBuilder private var statusBadge: some View {
        switch trip.status {
        case .onTime:
            Text("On time").font(.caption.bold()).foregroundStyle(.green)
        case .delayed:
            Text("Delayed").font(.caption.bold()).foregroundStyle(.orange)
        case .unrecognised, .missing:
            EmptyView()
        }
    }

    private var visibleIssues: [String] {
        trip.issues.compactMap(\.explanation).sorted()
    }
}

import SwiftUI

/// Changes the simulated endpoint's latency, rate limit and failure rate while the app runs.
/// This is how the live debrief's "new constraint" gets imposed without a rebuild.
struct NetworkConditionsSheet: View {
    @Environment(\.dismiss) private var dismiss
    @State private var conditions: NetworkConditions?

    var body: some View {
        NavigationStack {
            Form {
                if let binding = Binding($conditions) {
                    Section("Presets") {
                        ForEach(NetworkConditions.Preset.allCases) { preset in
                            Button(preset.title) { conditions = preset.conditions }
                        }
                    }
                    Section("Latency") {
                        Stepper("Base: \(binding.wrappedValue.baseLatency.milliseconds) ms",
                                value: milliseconds(binding.baseLatency), in: 0...10_000, step: 100)
                        Stepper("Jitter: up to \(binding.wrappedValue.jitter.milliseconds) ms",
                                value: milliseconds(binding.jitter), in: 0...10_000, step: 100)
                    }
                    Section {
                        Stepper(binding.wrappedValue.requestsPerWindow == 0
                                ? "Unlimited"
                                : "\(binding.wrappedValue.requestsPerWindow) requests / \(binding.wrappedValue.window.milliseconds / 1000) s",
                                value: binding.requestsPerWindow, in: 0...60)
                        Stepper("Window: \(binding.wrappedValue.window.milliseconds / 1000) s",
                                value: seconds(binding.window), in: 1...120)
                    } header: {
                        Text("Rate limit (HTTP 429)")
                    }
                    Section("Failures (HTTP 503)") {
                        Slider(value: binding.failureRate, in: 0...1, step: 0.05) {
                            Text("Failure rate")
                        }
                        Text("\(Int(binding.wrappedValue.failureRate * 100))% of requests fail")
                            .font(.caption)
                    }
                } else {
                    ProgressView()
                }
            }
            .navigationTitle("Network conditions")
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .confirmationAction) {
                    Button("Apply") {
                        if let conditions {
                            Task { await SimulatedBackend.shared.setConditions(conditions) }
                        }
                        dismiss()
                    }
                }
                ToolbarItem(placement: .cancellationAction) {
                    Button("Cancel") { dismiss() }
                }
            }
            .task { conditions = await SimulatedBackend.shared.conditions }
        }
    }

    private func milliseconds(_ binding: Binding<Duration>) -> Binding<Int> {
        Binding(get: { binding.wrappedValue.milliseconds }, set: { binding.wrappedValue = .milliseconds($0) })
    }

    private func seconds(_ binding: Binding<Duration>) -> Binding<Int> {
        Binding(get: { binding.wrappedValue.milliseconds / 1000 }, set: { binding.wrappedValue = .seconds($0) })
    }
}

