4	/// Routes `URLSession` requests for `SimulatedBackend.host` to the in-process backend.
5	/// Because this sits *under* URLSession, cancelling the Swift task that awaits
6	/// `URLSession.data(for:)` cancels the URLSessionTask, which calls `stopLoading()` here. That is the
7	/// same path a real request takes, so cancellation is tested end to end, not mocked.
8	///
9	/// Concurrency: URLProtocol isn't Sendable, so `self` crosses into the loading task in an
10	/// `UncheckedSendableBox`. That's sound here because the only mutable state, `inFlight`, is behind a
11	/// lock, and URLSession allows `client` callbacks from any thread for custom protocols.
12	final class SimulatedCityfloProtocol: URLProtocol {
13	    private let inFlight = OSAllocatedUnfairLock<Task<Void, Never>?>(initialState: nil)
14	
15	    override class func canInit(with request: URLRequest) -> Bool {
16	        request.url?.host() == SimulatedBackend.host
17	    }
18	
19	    override class func canonicalRequest(for request: URLRequest) -> URLRequest {
20	        request
21	    }
22	
23	    override func startLoading() {
24	        let request = self.request
25	        let protocolBox = UncheckedSendableBox(value: self)
26	        let task = Task {
27	            guard let response = await SimulatedBackend.shared.handle(request), !Task.isCancelled else { return }
28	            protocolBox.value.deliver(response, for: request)
29	        }
30	        inFlight.withLock { $0 = task }
31	    }
32	
